let notesUndo=null,notesReadError='',pendingClearNoteIds=null;
function getNotes(){try{const notes=RiskUserState.list();notesReadError='';return notes}catch(e){notesReadError=e.message;return []}}
function noteDialog(topic='七维研究'){
 modal('记录研究判断',`<form id="note-form"><div class="field"><label>研究标的</label><input value="${esc(asset().name)} · ${asset().code}" readonly></div><div class="field"><label for="note-kind">问题性质</label><select id="note-kind"><option>不确定</option><option>暂时性假设</option><option>结构性假设</option></select></div><div class="field"><label for="note-evidence">事实证据与来源</label><textarea id="note-evidence" required maxlength="800" placeholder="记录事实、出处和数据时间。"></textarea></div><div class="field"><label for="note-counter">反证与后续验证条件</label><textarea id="note-counter" required maxlength="800" placeholder="什么证据会推翻判断？什么时候复核？"></textarea></div><button class="btn primary" type="submit">保存到当前浏览器</button></form>`);
 $('#note-form').onsubmit=e=>{e.preventDefault();try{RiskUserState.add({code:state.code,name:asset().name,topic,kind:$('#note-kind').value,evidence:$('#note-evidence').value,counter:$('#note-counter').value,createdAt:new Date().toISOString(),time:new Date().toLocaleString('zh-CN',{timeZone:'Asia/Shanghai'}),environment:mode==='local'?'本地真实行情':isDemo()?'合成演示':'导入快照'});$('#dialog').close();render();toast('研究记录已保存')}catch(error){toast('保存失败：'+error.message)}}
}
function review(){
 const notes=getNotes(),undo=notesUndo?`<div class="record-undo" role="status"><span>已删除 ${notesUndo.length} 条研究记录，可在刷新页面前撤销。</span><button class="btn small" onclick="undoResearchNotes()">撤销删除</button></div>`:'';
 const actions=`<span class="muted small">${notes.length} 条 · 当前浏览器</span><button class="btn small danger" onclick="confirmClearResearchNotes()" ${!notes.length?'disabled':''}>清空全部</button>`;
 return title('研究复盘','保留判断的来由、反证和当时的数据环境。',selectAsset()+button('新增研究记录',"noteDialog()",true,'plus'))+`<div class="grid-three">${[['事实','记录财报、价格、事件原文与披露时间，不以最新数据冒充历史已知。'],['解释','区分情绪修复、经营改善和估值重估，保留不确定项。'],['验证','记录失效条件、样本外表现和未成交原因。']].map(([t,s])=>panel(t,`<div class="panel-body"><p class="muted small">${s}</p></div>`)).join('')}</div>${undo}${notesReadError?notice(esc(notesReadError)+'；现有记录未覆盖。'):''}${panel('研究记录',notes.length?`<div class="panel-body timeline">${notes.map(n=>`<article class="timeline-item" data-record-id="${n.id}"><div class="timeline-date">${esc(n.time)}<br>${esc(n.environment)}</div><div class="record-content"><div class="record-heading"><h3>${esc(n.name)} · ${esc(n.topic)} ${pill(esc(n.kind),'warn')}</h3><button class="btn small danger" aria-label="删除记录：${esc(n.name)} · ${esc(n.topic)}" onclick="confirmDeleteResearchNote('${n.id}')">删除记录</button></div><p><strong>事实与来源：</strong>${esc(n.evidence)}</p><p><strong>反证与验证：</strong>${esc(n.counter)}</p><button class="text-button" onclick="openRecordedAsset('${n.id}')">回到个股研究</button></div></article>`).join('')}</div>`:'<div class="empty">尚无研究记录。从七维分析、情绪偏离或本页新增一条判断。</div>',`<div class="actions">${actions}</div>`)}`
}
function confirmDeleteResearchNote(id){const note=getNotes().find(n=>n.id===id);if(!note)return toast('该记录已不存在，请刷新列表');modal('删除研究记录',`<p>删除这条研究记录？</p><div class="deletion-detail"><strong>${esc(note.name)} · ${esc(note.topic)}</strong><p class="muted small">${esc(note.time)}</p><p>${esc(note.evidence)}</p></div><p class="muted small">仅影响当前浏览器；删除后可在本页撤销，刷新后撤销失效。</p><div class="dialog-actions"><button class="btn" onclick="$('#dialog').close()">取消</button><button class="btn danger-solid" onclick="deleteResearchNote('${id}')">确认删除该条记录</button></div>`)}
function deleteResearchNote(id){try{const removed=RiskUserState.remove(id);if(removed.length)notesUndo=removed;$('#dialog').close();render();toast(removed.length?'已删除该条记录，可撤销':'该记录已不存在')}catch(e){toast('删除失败：'+e.message)}}
function confirmClearResearchNotes(){const notes=getNotes();if(!notes.length)return;pendingClearNoteIds=notes.map(n=>n.id);modal('清空全部研究记录',`<p>清空当前浏览器保存的全部 <strong>${notes.length}</strong> 条研究记录？</p><p class="muted small" style="margin-top:12px">此操作仅删除研究记录，不影响行情、研究参数或风格偏好。清空后可在本页撤销，刷新后撤销失效。</p><div class="dialog-actions"><button class="btn" onclick="$('#dialog').close();pendingClearNoteIds=null">取消</button><button class="btn danger-solid" onclick="clearResearchNotes()">确认清空全部记录</button></div>`)}
function clearResearchNotes(){if(!pendingClearNoteIds)return;try{const removed=RiskUserState.clear(pendingClearNoteIds);pendingClearNoteIds=null;if(removed.length)notesUndo=removed;$('#dialog').close();render();toast('已清空 '+removed.length+' 条研究记录，可撤销')}catch(e){pendingClearNoteIds=null;$('#dialog').close();render();toast('未清空：'+e.message)}}
function undoResearchNotes(){if(!notesUndo)return;try{const count=RiskUserState.restore(notesUndo);notesUndo=null;render();toast('已恢复 '+count+' 条研究记录')}catch(e){toast('撤销失败：'+e.message)}}

function openRecordedAsset(id){const note=getNotes().find(n=>n.id===id);if(note&&CATALOG.some(a=>a.code===note.code))setAsset(note.code,'research');else toast('该记录的研究标的不在当前清单中')}
